export function useCab(
  client: CommandClient,
  id: string,
  include?: CabInclude,
  options?: Record<string, unknown>
) {
  return {
    ...client.cab.getQueryOptions(id, include),
    ...options,
  };
}

export function useCabQuery(
  client: CommandClient,
  params?: {
    filter?: CabFilterInput;
    limit?: number;
    include?: CabInclude;
  },
  options?: Record<string, unknown>
) {
  const builder = client.cab.query();
  if (params?.filter) builder.filter(params.filter);
  if (params?.limit) builder.limit(params.limit);
  if (params?.include) builder.include(params.include);

  return {
    ...builder.queryOptions(),
    ...options,
  };
}

